/* ----- Action Plan ----- */
const NARR={A:'Lakukan komunikasi terarah{R} untuk memperkuat pemahaman dan alignment terhadap perubahan{C}.',D:'Lakukan engagement dan penanganan resistensi{R} untuk meningkatkan komitmen terhadap perubahan{C}.',K:'Siapkan dan sampaikan panduan kerja atau sosialisasi{R} untuk menutup gap pengetahuan{C}.',A2:'Laksanakan coaching, simulasi, atau praktik terarah{R} untuk memastikan kemampuan menjalankan perubahan{C}.',S:'Perbarui pemetaan stakeholder dan rencana engagement{R}{C}.',H:'Finalisasi kesiapan operasional, dukungan, dan mekanisme hypercare{R}{C}.',R:'Tetapkan ownership, monitoring adopsi, dan reinforcement{R}{C}.'};
function narrFor(dim,role,ctxText,root){const R=role&&role!=='Lintas Role'?' untuk role '+role:'',c=trim(ctxText,150),C=c?' terkait '+c:'';let o=(NARR[dim]||'Susun dan laksanakan tindak lanjut terarah{R}{C}.').replace('{R}',R).replace('{C}',C);if(root)o+=' Fokus pada akar masalah: '+trim(root,220)+'.';return o.replace(/\.\./g,'.')}
const SRC_LABEL={critical:'Critical Gate',root_cause:'Root Cause Jawaban Rendah',analytics_gap:'Gap Analytics',role_gap:'Readiness Role',manual:'Manual'};
/* kompatibel dengan action plan lama Modul Transformasi (title/root/due/priority) */
function normAction(a){if(a.__n)return a;a.code=a.code||a.id;a.actionNarrative=a.actionNarrative||a.title||'';a.rootCause=a.rootCause??a.root??'';a.dueDate=a.dueDate||a.due||'';a.sourceType=a.sourceType||(String(a.sourceKey||'').includes(':')?'critical':'manual');a.source=a.source||(a.sourceType==='manual'?'Manual':'Critical Gate');a.decision=a.decision||(a.activityId?'approved':'pending');if(a.status==='Completed')a.status='Done';if(a.status==='Cancelled')a.status='Blocked';a.status=a.status||'Open';a.__n=1;return a}
const actionsOf=sid=>db().actions.filter(a=>a.surveyId===sid).map(normAction).sort((a,b)=>String(a.dueDate||'9999').localeCompare(String(b.dueDate||'9999')));
function codeFor(rows,role,dim){const base=(ROLE_CODE[role]||ROLE_CODE[Object.keys(ROLE_TITLE).find(k=>ROLE_TITLE[k]===role)]||'GEN')+'-'+(DIM_CODE[dim]||'X');let n=1;const ids=new Set(rows.map(r=>r.code));while(ids.has(base+n))n++;return base+n}
function generateActions(s){if(!can())return notify('Akses kelola Action Plan tidak tersedia');const A=analyze(s);if(!A.rows.length)return notify('Belum ada respons untuk dianalisis');if(s.actionPlanClosed)return notify('Action Plan ditutup. Buka kembali terlebih dahulu.');
 const existing=actionsOf(s.id),pool=existing.map(r=>({code:r.code})),due=new Date(Date.now()+14*864e5).toISOString().slice(0,10),list=[];
 const code=(ok,role,dim)=>{const f=existing.find(r=>r.originKey===ok);if(f)return f.code;const c=codeFor(pool,role,dim);pool.push({code:c});return c};
 A.crit.filter(x=>x.avg<4).slice(0,8).forEach(x=>{const ok='CRIT_'+x.q.id,role=qRoles(x.q).includes('ALL')?'Lintas Role':roleTitle(qRoles(x.q)[0]),root=[...new Set(A.roots.filter(r=>r.q.id===x.q.id).map(r=>r.why))].slice(0,3).join(' | ');
  list.push({code:code(ok,role,x.q.dimension),originKey:ok,sourceType:'critical',title:'Tindak lanjut Critical Gate '+x.q.id,dimension:x.q.dimension,role,gapPct:x.pct,source:'Critical Gate '+x.avg.toFixed(2)+'/5',rootCause:root,actionNarrative:narrFor(x.q.dimension,role,sysText(x.q.text,s),root)})});
 const groups=new Map();A.roots.forEach(x=>{const k=x.q.id;if(!groups.has(k))groups.set(k,{q:x.q,reasons:[],roles:new Set()});const g=groups.get(k);if(!g.reasons.some(r=>r.toLowerCase()===x.why.toLowerCase()))g.reasons.push(x.why);x.role.split(', ').forEach(r=>g.roles.add(r))});
 [...groups.values()].slice(0,10).forEach(g=>{if(list.some(a=>a.originKey==='CRIT_'+g.q.id))return;const ok='ROOT_'+g.q.id,qr=qRoles(g.q),role=qr.includes('ALL')?(g.roles.size===1?[...g.roles][0]:'Lintas Role'):roleTitle(qr[0]),root=g.reasons.slice(0,3).join(' | ');
  list.push({code:code(ok,role,g.q.dimension),originKey:ok,sourceType:'root_cause',title:'Tindak lanjut Root Cause '+g.q.id,dimension:g.q.dimension,role,source:'Jawaban rendah',rootCause:root,actionNarrative:narrFor(g.q.dimension,role,sysText(g.q.text,s),root)})});
 const cov=new Set(list.map(a=>a.dimension));A.weak.slice(0,5).forEach(d=>{if(cov.has(d.dim))return;const ok='DIM_'+d.dim;list.push({code:code(ok,'Lintas Role',d.dim),originKey:ok,sourceType:'analytics_gap',title:'Tindak lanjut gap '+d.label,dimension:d.dim,role:'Lintas Role',gapPct:d.pct,source:'Dimensi '+d.label+' '+d.pct+'%',rootCause:'',actionNarrative:narrFor(d.dim,'Lintas Role','skor readiness '+d.pct+'%')});cov.add(d.dim)});
 A.rm.filter(r=>r.n>=PRIV_N).forEach(r=>{const low=Object.entries(r.dims).filter(([,v])=>v!=null).map(([k,v])=>({k,p:pctOf(v)})).sort((a,b)=>a.p-b.p)[0];if(!low||low.p>=70)return;const role=roleTitle(r.role);if(list.some(a=>a.role===role&&a.dimension===low.k))return;const ok='ROLE_'+r.role+'_'+low.k;
  list.push({code:code(ok,role,low.k),originKey:ok,sourceType:'role_gap',title:'Tindak lanjut '+role+' — '+(DIM_FULL[low.k]||low.k),dimension:low.k,role,gapPct:low.p,source:'Role readiness '+low.p+'%',rootCause:'',actionNarrative:narrFor(low.k,role,'skor readiness role '+low.p+'%')})});
 const by=ctx.ME?.email||'';list.forEach(a=>{const prev=existing.find(r=>r.code===a.code);if(prev){Object.assign(prev,{...a,actionNarrative:prev.actionNarrative||a.actionNarrative,updated:now(),updatedBy:by})}else db().actions.push({id:uuid(),surveyId:s.id,...a,pic:'',dueDate:due,status:'Open',evidence:'',notes:'',decision:'pending',activityId:'',created:now(),createdBy:by,updated:now()})});
 save();apSurvey=s.id;tab='actions';selected='';render();notify(list.length+' action disiapkan · '+list.filter(a=>a.sourceType==='critical').length+' Critical Gate · '+list.filter(a=>a.sourceType==='root_cause').length+' Root Cause')}
function actRef(code,sid){return db().actions.find(a=>a.surveyId===sid&&(a.code||a.id)===code)}
function activityOf(a){return a&&a.activityId?(ctx.S.oneonone||[]).find(x=>x.id===a.activityId):null}
function sendToActivity(s,a){if(!a)return;const narr=String(a.actionNarrative||'').trim(),pic=String(a.pic||'').trim(),due=String(a.dueDate||'').trim();
 if(!narr)return notify('Narasi tindak lanjut wajib diisi.');if(!pic)return notify('Isi PIC terlebih dahulu.');if(!due)return notify('Isi Target Tindak Lanjut terlebih dahulu.');
 if(activityOf(a)){a.decision='approved';a.approvedAt=a.approvedAt||now();save();return render()}
 const first=(narr.match(/^.*?[.!?](?:\s|$)/)||[narr])[0].trim(),mod=ctx.mods().find(m=>m.kode===s.module),uidF=typeof window.uid==='function'?window.uid:uuid;
 const x={id:uidF(),keAkt:true,tahun:+due.slice(0,4),tw:Math.ceil(+due.slice(5,7)/3),no:0,kat:'T-Survey',nama:'[CRA] '+trim(first,185),tgl:due,jam:'',program:mod?.nama||s.system||s.name,tema:'',uic:'',spv:'',katim:'',anggota:'',lokasi:'',mode:'Offline',pic:pic.split(/\s*[,;]\s*/).filter(Boolean),layanan:'Tidak',unitP:mod?.uic||'',tujuan:narr,stat:a.status==='Done'?'Selesai':'',
  catatan:['CRA Action Plan '+a.code,'Survey: '+s.name,'Sumber: '+(a.source||SRC_LABEL[a.sourceType]||''),a.rootCause?'Root Cause: '+a.rootCause:'',a.notes?'Catatan: '+a.notes:'',a.evidence?'Evidence: '+a.evidence:''].filter(Boolean).join(' · '),craAction:{surveyId:s.id,code:a.code}};
 try{if(typeof window.actOwnNew==='function')x.own=window.actOwnNew()}catch(err){}try{if(typeof window.actStamp==='function')window.actStamp(x)}catch(err){}
 ctx.S.oneonone=ctx.S.oneonone||[];ctx.S.oneonone.push(x);Object.assign(a,{decision:'approved',activityId:x.id,approvedAt:now(),approvedBy:ctx.ME?.email||'',updated:now()});save();render();notify('Action '+a.code+' ditindaklanjuti dan masuk ke Aktivitas')}
function actionPlan(){if(!db().surveys.length)return '<section class="cra2-panel"><div class="cra2-empty"><b>Belum ada survei</b>Action Plan dibuat dari Analytics.</div></section>';
 apSurvey=pickSurvey(apSurvey||anSurvey);const s=survey(apSurvey),rows=actionsOf(s.id),closed=!!s.actionPlanClosed,ed=can();
 const cnt=k=>rows.filter(a=>a.decision===k).length,done=rows.filter(a=>a.decision==='approved'&&a.status==='Done').length;
 return '<section class="cra2-panel"><div class="cra2-line cra2-head"><div><h3>Readiness Action Plan</h3><p class="cra2-sub">Critical Gate / root cause jawaban rendah → narasi tindak lanjut → keputusan → Aktivitas → monitoring. Action Plan tetap menjadi master record.</p></div>'+surveySelect('cra2-ap-sel',apSurvey)+'</div>'+
 '<div class="cra2-ap-bar"><div class="cra2-ap-sum"><span>'+rows.length+' total action</span><span class="pending">'+cnt('pending')+' menunggu</span><span class="approved">'+cnt('approved')+' ditindaklanjuti</span><span class="rejected">'+cnt('rejected')+' ditolak</span><span>'+done+' selesai</span>'+(closed?'<span class="closed">🔒 Ditutup</span>':'')+'</div><div class="cra2-ap-btns">'+(!ed?'':closed?button('ap-reopen','↺ Buka Kembali','',s.id):button('ap-manual','＋ Action Manual','',s.id)+button('an-generate','⟳ Generate dari Analytics','gold',s.id)+button('ap-close','🔒 Tutup Action Plan','danger',s.id))+'</div></div>'+
 (rows.length?'<div class="cra2-table cra2-ap"><table><colgroup><col style="width:96px"><col style="width:380px"><col style="width:120px"><col style="width:140px"><col style="width:150px"><col style="width:150px"><col style="width:130px"><col style="width:170px"><col style="width:190px"><col style="width:130px"></colgroup><thead><tr><th>Kode</th><th>Rencana Tindak Lanjut / Sumber</th><th>Peran</th><th>PIC</th><th>Target Tindak Lanjut</th><th>Keputusan</th><th>Status</th><th>Evidence</th><th>Catatan</th><th>Aktivitas</th></tr></thead><tbody>'+rows.map(a=>{const d=a.decision,act=activityOf(a),nEd=ed&&!closed&&d==='pending',xEd=ed&&!closed&&d==='approved',edit=ed&&!closed&&d!=='rejected',k=e(a.code);
  return '<tr class="'+d+(a.status==='Done'?' done':'')+'" data-ap="'+k+'"><td><span class="cra2-code">'+k+'</span></td><td class="narr"><textarea data-ap-f="actionNarrative"'+(nEd?'':' disabled')+'>'+e(a.actionNarrative)+'</textarea><div class="src"><span class="cra2-src '+(a.sourceType==='critical'?'critical':a.sourceType==='root_cause'?'root':a.sourceType==='manual'?'manual':'analytics')+'">'+e(SRC_LABEL[a.sourceType]||'Analytics')+'</span><span>'+e(a.source||'Manual')+' · '+e(DIM_FULL[a.dimension]||a.dimension||'')+'</span></div>'+(a.rootCause?'<div class="root"><b>Root Cause:</b> '+e(a.rootCause)+'</div>':'')+'</td>'+
  '<td>'+e(a.role||'Lintas Role')+'</td><td><input data-ap-f="pic" value="'+e(a.pic||'')+'" placeholder="Nama PIC"'+(edit?'':' disabled')+'></td><td><input type="date" data-ap-f="dueDate" value="'+e(a.dueDate||'')+'"'+(edit?'':' disabled')+'></td>'+
  '<td>'+(d==='pending'?(closed||!ed?'<span class="cra2-dec pending">Menunggu Keputusan</span>':'<div class="cra2-decb">'+button('ap-follow','✓ Tindak Lanjuti','gold',a.code)+button('ap-reject','× Tolak','danger',a.code)+'</div>'):d==='approved'?'<span class="cra2-dec approved">✓ Ditindaklanjuti</span>':'<div class="cra2-decb"><span class="cra2-dec rejected">× Ditolak</span>'+(closed||!ed?'':button('ap-review','↺ Tinjau Ulang','',a.code))+'</div>')+'</td>'+
  '<td><select data-ap-f="status"'+(xEd?'':' disabled')+'>'+['Open','In Progress','Done','Blocked'].map(x=>'<option'+(a.status===x?' selected':'')+'>'+x+'</option>').join('')+'</select></td><td><textarea data-ap-f="evidence" placeholder="Link/bukti..."'+(xEd?'':' disabled')+'>'+e(a.evidence||'')+'</textarea></td><td><textarea data-ap-f="notes" placeholder="Catatan keputusan/pelaksanaan..."'+(ed&&!closed?'':' disabled')+'>'+e(a.notes||'')+'</textarea></td>'+
  '<td>'+(act?'<span class="cra2-lock">✓ Aktivitas</span><small>'+e(act.stat||'Terjadwal')+'</small>':d==='approved'&&!closed&&ed?button('ap-resend','↻ Kirim Ulang','',a.code):'<span class="cra2-lock off">—</span>')+'</td></tr>'}).join('')+'</tbody></table></div>':'<div class="cra2-empty"><b>Belum ada action</b>Generate action dari Analytics atau tambah manual.</div>')+'</section>'}
function apModal(title,body,okLabel,onOk){const ov=document.createElement('div');ov.className='cra2-ov';ov.innerHTML='<div class="cra2-md"><div class="hd"><b>'+title+'</b><button type="button" data-x>×</button></div><div class="bd">'+body+'<div class="cra2-err"></div></div><div class="ft"><button type="button" class="cra2-button" data-x>Batal</button><button type="button" class="cra2-button primary" data-ok>'+okLabel+'</button></div></div>';document.body.appendChild(ov);
 ov.addEventListener('click',ev=>{if(ev.target===ov||ev.target.closest('[data-x]'))return ov.remove();if(ev.target.closest('[data-ok]')){const err=onOk(ov);if(err){ov.querySelector('.cra2-err').textContent=err;return}ov.remove()}});setTimeout(()=>ov.querySelector('textarea,input,select')?.focus(),30);return ov}
function execBrief(s){const A=analyze(s),acts=actionsOf(s.id),w=window.open('','_blank');if(!w)return notify('Pop-up diblokir peramban');
 const rowsD=A.dims.map(d=>'<tr><td>'+e(d.label)+'</td><td style="text-align:right">'+d.pct+'%</td></tr>').join(''),crit=A.crit.filter(x=>x.avg<4).sort((a,b)=>a.avg-b.avg).map(x=>'<li><b>'+e(x.q.id)+' ('+x.avg.toFixed(2)+'/5)</b> — '+e(sysText(x.q.text,s))+'</li>').join('');
 w.document.write('<html><head><meta charset="utf-8"><title>Executive Brief CRA — '+e(s.name)+'</title><style>body{font:13px/1.5 Arial,sans-serif;color:#13223f;max-width:820px;margin:28px auto;padding:0 20px}h1{font-size:20px;margin:0}h2{font-size:14px;margin:20px 0 6px;color:#173a74;border-bottom:2px solid #d9ad4b;padding-bottom:4px}.g{padding:12px 14px;border-radius:10px;background:#eef3fb;margin:12px 0}.k{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.k div{border:1px solid #dfe5ee;border-radius:8px;padding:8px}.k b{display:block;font-size:18px}table{border-collapse:collapse;width:100%}td,th{border-bottom:1px solid #e4e9f0;padding:5px 6px;text-align:left}small{color:#5a6b86}@media print{button{display:none}}</style></head><body><button onclick="print()" style="float:right">Cetak / PDF</button><h1>Executive Brief — Change Readiness Assessment</h1><small>'+e(s.name)+' · '+e(s.system||'')+' · '+e(s.round||'')+' · dicetak '+new Date().toLocaleDateString('id-ID',{day:'numeric',month:'long',year:'numeric'})+'</small>'+
 '<div class="g"><b>'+A.gate.label+' — '+A.pct+'%</b><br>'+e(A.gate.detail)+'</div><div class="k"><div><small>Overall</small><b>'+A.pct+'%</b></div><div><small>Respons</small><b>'+A.rows.length+'</b>'+(A.target?'<small>target '+A.target+'</small>':'')+'</div><div><small>Bottleneck</small><b style="font-size:14px">'+(A.weak[0]?e(A.weak[0].label)+' '+A.weak[0].pct+'%':'Tidak ada')+'</b></div><div><small>Critical Gate &lt;4/5</small><b>'+A.crit.filter(x=>x.avg<4).length+'</b></div></div>'+
 '<h2>Readiness per Dimensi</h2><table>'+rowsD+'</table><h2>Critical Gate yang Perlu Ditutup</h2>'+(crit?'<ol>'+crit+'</ol>':'<p>Tidak ada.</p>')+'<h2>Rekomendasi</h2><ul>'+insightsOf(A.weak,A.rm,A.crit).map(x=>'<li><b>'+e(x.title)+'</b> — '+e(x.text)+'</li>').join('')+'</ul>'+(acts.length?'<h2>Action Plan ('+acts.length+')</h2><table><tr><th>Kode</th><th>Tindak lanjut</th><th>PIC</th><th>Target</th><th>Keputusan</th></tr>'+acts.map(a=>'<tr><td>'+e(a.code)+'</td><td>'+e(a.actionNarrative)+'</td><td>'+e(a.pic||'—')+'</td><td>'+e(a.dueDate||'—')+'</td><td>'+(a.decision==='approved'?'Ditindaklanjuti':a.decision==='rejected'?'Ditolak':'Menunggu')+'</td></tr>').join('')+'</table>':'')+'</body></html>');w.document.close()}

/* ---------- Data dummy CRA (2026-11-24) ----------
   Untuk melihat hasil Analisis/Perbandingan/Rencana Aksi tanpa menunggu responden.
   Tanpa batasan waktu pengisian: survei dummy tidak punya tanggal akhir dan respons dummy langsung masuk.
   Setiap respons dummy ditandai dummy:true sehingga bisa dihapus sekaligus. */
const dummyCount=id=>resp(id).filter(r=>r.dummy).length;
const curModule=()=>{const m=String(location.hash||'').match(/^#modul-(.+)-t-cra$/);return m?decodeURIComponent(m[1]):''};
const DUMMY_UNITS=['Ditjen Anggaran','Ditjen Perbendaharaan','Sekretariat Jenderal','Ditjen Pajak','Ditjen Bea dan Cukai','BaTii','Pusmantap','Ditjen Kekayaan Negara'];
const DUMMY_WHY=['Belum ada sosialisasi yang menjelaskan perubahan proses ini.','Panduan dan SOP baru belum tersedia.','Akses ke aplikasi uji coba belum diberikan.','Jadwal pelatihan bentrok dengan beban kerja rutin.','Belum jelas siapa PIC dan jalur eskalasi bila ada kendala.','Pimpinan unit belum memberi arahan yang tegas.','Dokumentasi teknis dan known issue belum diserahkan.','Data uji belum lengkap sehingga belum bisa mencoba skenario nyata.'];
const DUMMY_TEXT=['Perlu sosialisasi lanjutan sebelum go-live.','Butuh panduan singkat dan video tutorial.','Jadwal pelatihan agar disesuaikan dengan beban kerja akhir bulan.','Sudah cukup jelas, tinggal pendampingan saat implementasi.','Perlu kepastian dukungan helpdesk setelah go-live.','Integrasi dengan aplikasi lama masih menjadi kekhawatiran.'];
function dummyResponses(s,n){const qs=s.questions||[],dims=[...new Set(qs.map(q=>q.dimension))],rnd=(a,b)=>a+Math.random()*(b-a);
 const base={};dims.forEach(d=>base[d]=rnd(2.6,4.5));const crit=rnd(-0.9,0.2),out=[];
 for(let i=0;i<n;i++){const pool=ROLES.slice(1).sort(()=>Math.random()-.5),rl=pool.slice(0,Math.random()<.25?2:1),bias=rnd(-0.7,0.7),ans={};
  qs.filter(q=>(q.roles||['ALL']).includes('ALL')||(q.roles||[]).some(x=>rl.includes(x))).forEach(q=>{
   if(q.type==='text'){if(Math.random()<.6)ans[q.id]=DUMMY_TEXT[Math.floor(Math.random()*DUMMY_TEXT.length)];return}
   ans[q.id]=Math.max(1,Math.min(5,Math.round((base[q.dimension]||3.5)+bias+(q.critical?crit:0)+rnd(-0.9,0.9))));if(ans[q.id]<=2&&Math.random()<.7)ans[q.id+'_why']=DUMMY_WHY[Math.floor(Math.random()*DUMMY_WHY.length)]});
  const d=new Date(Date.now()-Math.floor(rnd(0,14))*864e5-Math.floor(rnd(0,8))*36e5);
  out.push({id:uuid(),surveyId:s.id,name:'Responden Dummy '+String(resp(s.id).length+i+1).padStart(2,'0'),unit:DUMMY_UNITS[i%DUMMY_UNITS.length],roles:rl,answers:ans,email:'',created:d.toISOString(),dummy:true})}
 return out}
function dummySurvey(){const mk=curModule(),mod=ctx.mods().find(m=>m.kode===mk);const sys=mod?.nama||'Sistem Uji Coba';
 const sv={name:'Survei Dummy CRA'+(mk?' · '+mk:''),system:sys,series:'Dummy '+(mk||'CRA'),round:'Baseline',module:mk,moduleName:mod?.nama||'',year:Number(ctx.S.ui?.tahun)||new Date().getFullYear(),target:30,end:'',description:'Data uji coba (dummy) untuk melihat tampilan hasil CRA. Tanpa batas waktu pengisian.',questions:JSON.parse(JSON.stringify(db().bank)),anonymous:false,id:uuid(),status:'Aktif',created:now(),updated:now(),dummy:true};
 db().surveys.unshift(sv);return sv}
function fillDummy(id){if(!can())return notify('Akses tidak tersedia');let s=id?survey(id):null;
 if(!s){const mk=curModule();s=db().surveys.find(x=>x.status==='Aktif'&&(!mk||x.module===mk))||dummySurvey()}
 if(!s.questions?.length)return notify('Survei belum memiliki pertanyaan');
 const n=Math.max(5,Math.min(60,Number(s.target)||30)),rows=dummyResponses(s,n);db().responses.push(...rows);s.updated=now();save();selected=s.id;tab='active';render();notify(n+' respons dummy ditambahkan ke "'+s.name+'"')}
function clearDummy(id){if(!can())return;const n=dummyCount(id);if(!n)return;if(!confirm('Hapus '+n+' respons dummy dari survei ini?'))return;const v=db();v.responses=v.responses.filter(r=>!(r.surveyId===id&&r.dummy));const s=survey(id);if(s&&s.dummy&&!resp(id).length){v.surveys=v.surveys.filter(x=>x.id!==id);selected=''}save();render();notify(n+' respons dummy dihapus')}
function act(b){const a=b.dataset.cra2,id=b.dataset.id;
if(a==='dummy-fill')return fillDummy(id);
if(a==='an-generate')return generateActions(survey(id));
if(a==='exec-brief')return execBrief(survey(id));
if(a==='ap-follow'||a==='ap-resend'){const s=survey(apSurvey),x=actRef(id,apSurvey),tr=b.closest('[data-ap]');if(!s||!x)return;if(tr){const v=f=>tr.querySelector('[data-ap-f="'+f+'"]');['actionNarrative','pic','dueDate','notes'].forEach(f=>{if(v(f)&&!v(f).disabled)x[f]=v(f).value.trim()})}return sendToActivity(s,normAction(x))}
if(a==='ap-reject'){const x=actRef(id,apSurvey);if(!x)return;return apModal('Tolak Action '+e(id),'<p class="cra2-sub">Catatan penolakan wajib diisi agar alasan keputusan tetap terdokumentasi di Action Plan.</p><textarea class="cra2-ta" placeholder="Alasan penolakan...">'+e(x.notes||'')+'</textarea>','Tolak',ov=>{const why=ov.querySelector('textarea').value.trim();if(!why)return 'Catatan penolakan wajib diisi.';Object.assign(x,{decision:'rejected',notes:why,rejectedAt:now(),rejectedBy:ctx.ME?.email||'',updated:now()});save();render();notify('Action '+id+' ditolak')})}
if(a==='ap-review'){const x=actRef(id,apSurvey);if(!x)return;Object.assign(x,{decision:'pending',rejectedAt:'',updated:now()});save();render();return notify('Action '+id+' kembali menunggu keputusan')}
if(a==='ap-manual'){const s=survey(id);if(!s)return;return apModal('Tambah Action Manual','<label class="cra2-fl">Rencana Tindak Lanjut<textarea class="cra2-ta" data-m="n" placeholder="Contoh: Laksanakan workshop terarah untuk role Operasional agar dapat mempraktikkan proses dukungan baru."></textarea></label><div class="cra2-fields"><label>Role<select data-m="r"><option value="Lintas Role">Lintas Role</option>'+ROLES.filter(x=>x!=='ALL').map(x=>'<option value="'+e(roleTitle(x))+'">'+e(roleTitle(x))+'</option>').join('')+'</select></label><label>Dimensi<select data-m="d">'+DIM_ORDER.map(d=>'<option value="'+d+'">'+e(DIM_FULL[d])+'</option>').join('')+'</select></label></div><p class="cra2-sub">Kode action dibuat otomatis. Action baru berstatus Menunggu Keputusan dan belum masuk Aktivitas sampai dipilih Tindak Lanjuti.</p>','Simpan Action',ov=>{const n=ov.querySelector('[data-m="n"]').value.trim(),role=ov.querySelector('[data-m="r"]').value,dim=ov.querySelector('[data-m="d"]').value;if(!n)return 'Rencana tindak lanjut wajib diisi.';const code=codeFor(actionsOf(s.id),role,dim);db().actions.push({id:uuid(),surveyId:s.id,code,title:'Action Manual '+code,actionNarrative:n,dimension:dim,role,source:'Manual',sourceType:'manual',rootCause:'',pic:'',dueDate:new Date(Date.now()+14*864e5).toISOString().slice(0,10),status:'Open',decision:'pending',evidence:'',notes:'',activityId:'',created:now(),createdBy:ctx.ME?.email||'',updated:now()});save();render();notify('Action '+code+' ditambahkan')})}
if(a==='ap-close'){const s=survey(id),rows=actionsOf(id),pend=rows.filter(x=>x.decision==='pending').length,open=rows.filter(x=>x.decision==='approved'&&x.status!=='Done').length;if(pend)return notify(pend+' action masih menunggu keputusan. Tindak lanjuti atau tolak terlebih dahulu.');if(open)return notify(open+' action yang ditindaklanjuti belum berstatus Done.');if(!confirm('Tutup Action Plan ini? Seluruh action menjadi read-only sampai dibuka kembali.'))return;Object.assign(s,{actionPlanClosed:true,actionPlanClosedAt:now(),actionPlanClosedBy:ctx.ME?.email||''});save();return render()}
if(a==='ap-reopen'){const s=survey(id);Object.assign(s,{actionPlanClosed:false,actionPlanReopenedAt:now()});save();return render()}
if(a==='dummy-clear')return clearDummy(id);
if(a==='tab'){tab=b.dataset.v;selected='';responding='';actionEdit='';if(tab==='create'&&!draft)newDraft();return render()}
if(a==='bank-edit'){if(!can())return notify('Akses edit bank tidak tersedia');syncDraft();bankEditId=id;return render()}
if(a==='bank-edit-cancel'){bankEditId='';return render()}
if(a==='bank-edit-save'){if(!can())return;const q=db().bank.find(x=>x.id===bankEditId);if(!q)return;const get=k=>document.getElementById('cra2-edit-'+k);const text=get('text')?.value.trim();if(!text)return notify('Pertanyaan tidak boleh kosong');q.text=text;q.note=get('note')?.value||'';q.dimension=get('dim')?.value||'A';q.dimensionLabel=DIM[q.dimension]||q.dimension;q.roles=[get('role')?.value||'ALL'];q.type=get('type')?.value||'likert';q.required=!!get('required')?.checked;q.critical=!!get('critical')?.checked;const d=draft?.questions.find(x=>x.id===q.id);if(d&&!(editing&&resp(editing).length))Object.assign(d,JSON.parse(JSON.stringify(q)));save();bankEditId='';notify('Bank pertanyaan disimpan');return render()}
if(a==='bank-import')return document.getElementById('cra2-import')?.click();
if(a==='bank-xlsx')return exportExcel('CRA_Bank_Pertanyaan.xlsx',bankRows(),'Bank Pertanyaan');
if(a==='bank-json')return exportFile('CRA_Bank_Pertanyaan.json',JSON.stringify({bank:db().bank},null,2));
if(a==='new-q'){if(!can())return notify('Akses bank tidak tersedia');sync();const q={id:uuid(),dimension:'A',dimensionLabel:'Awareness',roles:['ALL'],text:'Pertanyaan baru',note:'',type:'likert',required:true,critical:false};db().bank.push(q);draft.questions.push({...q});save();return render()}
if(a==='include-q'){if(!can())return notify('Akses konfigurasi tidak tersedia');sync();const q=db().bank.find(x=>x.id===id),i=draft.questions.findIndex(x=>x.id===id);if(!q)return;if(i>=0)draft.questions.splice(i,1);else draft.questions.push({...q});return render()}
if(['move-up','move-down','remove-q'].includes(a)){if(!can())return notify('Akses konfigurasi tidak tersedia');sync();const qid=b.closest('[data-qid]')?.dataset.qid,idx=draft.questions.findIndex(q=>q.id===qid);if(idx<0)return;if(a==='remove-q')draft.questions.splice(idx,1);else{const dest=idx+(a==='move-up'?-1:1);if(dest>=0&&dest<draft.questions.length)[draft.questions[idx],draft.questions[dest]]=[draft.questions[dest],draft.questions[idx]]}return render()}
if(a==='draft-cancel'){draft=null;tab='active';return render()}
if(a==='save-survey'){if(!can())return notify('Tidak memiliki hak akses');sync();if(!draft.name.trim()||!draft.questions.length)return notify('Nama survei dan pertanyaan wajib');const existing=survey(editing);if(existing&&resp(editing).length)return notify('Survei dengan respons terkunci: buat versi baru');const mod=ctx.mods().find(m=>m.kode===draft.module);const obj={...draft,id:existing?.id||uuid(),moduleName:mod?.nama||'',year:Number(draft.year)||ctx.S.ui.tahun,status:'Aktif',created:existing?.created||now(),updated:now()};if(existing)Object.assign(existing,obj);else db().surveys.unshift(obj);save();draft=null;editing='';tab='active';notify('Survei tersimpan');return render()}
if(a==='detail'){selected=id;return render()}
if(a==='back'){selected='';responding='';return render()}
if(a==='respond'){if(!can())return notify('Akses tidak tersedia');responding=id;selected='';roles=['Probis'];answers={};respondentName=ctx.ME?.nama||'';respondentUnit='';return render()}
if(a==='submit-response'){if(!can())return notify('Akses tidak tersedia');const s=survey(responding);if(!s)return;const qs=s.questions.filter(q=>(q.roles||['ALL']).includes('ALL')||(q.roles||[]).some(r=>roles.includes(r)));if(!roles.length)return notify('Pilih minimal satu role');if(qs.some(q=>q.required!==false&&!answers[q.id]))return notify('Lengkapi semua pertanyaan wajib');const get=k=>document.querySelector('[name="'+k+'"]')?.value||'';db().responses.push({id:uuid(),surveyId:s.id,name:get('respondent')||ctx.ME?.nama,unit:get('unit'),roles:[...roles],answers:{...answers},email:ctx.ME?.email,created:now()});save();selected=s.id;responding='';notify('Respons disimpan');return render()}
if(a==='edit-survey'){const s=survey(id);if(!can())return;newDraft(s);selected='';tab='create';return render()}
if(a==='toggle'){if(!can())return;const s=survey(id);s.status=s.status==='Aktif'?'Ditutup':'Aktif';save();return render()}
if(a==='responses-export'){const s=survey(id);return exportExcel('CRA_Responses_'+id+'.xlsx',resp(id).map(r=>({Name:r.name,Roles:r.roles.join(', '),Unit:r.unit,Date:r.created,...r.answers})),'Responses')}
if(a==='action-generate'){if(!can())return notify('Akses kelola Action Plan tidak tersedia');let n=0;for(const s of db().surveys){const rows=resp(s.id);if(!rows.length)continue;for(const q of s.questions.filter(q=>q.critical)){const values=rows.map(r=>Number(r.answers?.[q.id])).filter(x=>x>=1&&x<=5);if(!values.length)continue;const avg=values.reduce((a,b)=>a+b,0)/values.length;if(avg>2)continue;const key=s.id+':'+q.id;if(db().actions.some(x=>x.sourceKey===key))continue;db().actions.push({id:uuid(),sourceKey:key,surveyId:s.id,title:'Tindak lanjut Critical Gate: '+q.text,root:'Nilai rata-rata '+avg.toFixed(2)+'/5 pada item kritikal '+q.id,pic:'',priority:'Critical',due:'',status:'Open',updated:now()});n++}}if(n)save();notify(n+' tindak lanjut Critical Gate dibuat');return render()}
if(a==='action-add'){actionEdit='new';return render()}
if(a==='action-edit'){actionEdit=id;return render()}
if(a==='action-cancel'){actionEdit='';return render()}
if(a==='action-save'){if(!can())return notify('Akses tidak tersedia');const val=n=>document.querySelector('[name="'+n+'"]')?.value||'';if(!val('atitle'))return notify('Action wajib diisi');let o=db().actions.find(x=>x.id===actionEdit);if(!o){o={id:uuid()};db().actions.push(o)}Object.assign(o,{surveyId:val('asurvey'),title:val('atitle'),root:val('aroot'),pic:val('apic'),priority:val('apriority'),due:val('adue'),status:val('astatus'),updated:now()});save();actionEdit='';return render()}
}
